import itertools

def check_m_prime(m):
    from itertools import combinations_with_replacement, permutations

    def get_all_permutations_sums_mod(residues, m):
        sums = set()
        for p in set(permutations(residues)):
            val = sum((i + 1) * p[i] for i in range(m))
            sums.add(val % m)
        return sums

    for residues in combinations_with_replacement(range(m), m):
        if len(set(residues)) == 1:
            continue # All same, Condition 1 is satisfied

        # If the residues are not all the same, Condition 2 should be satisfied
        # by checking if 0 is in the possible sums.
        # Wait, the condition is (Condition 1 OR Condition 2).
        # If Condition 1 is not satisfied, Condition 2 MUST be satisfied.
        if sum(residues) % m != 0:
            sums = get_all_permutations_sums_mod(residues, m)
            if 0 not in sums:
                return False, residues
    return True, None

