import itertools

def check_m_v4(m):
    # Using the fact that we only need to check multisets where sum(R) % m != 0.
    # And we can use a more efficient way to find if 0 is in the possible sums.
    from itertools import combinations_with_replacement, permutations

    def get_all_possible_sums(residues, m):
        # dp[i][s] = set of multisets (as tuples of counts) of residues that can form sum s with weights 1..i
        # This is still too slow. Let's use the fact that for a given multiset,
        # we can use the counts of each residue.
        counts = [0] * m
        for r in residues:
            counts[r] += 1

        # dp[i][s] = possible counts of residues used for sum s with weights 1..i
        # Still too complex. Let's use the property that we only need to check for ONE permutation.
        # For a fixed multiset, we can use backtracking to find if any permutation works.

        res_list = sorted(residues)
        n = len(res_list)
        used = [False] * n

        def backtrack(idx, current_sum):
            if idx == n:
                return current_sum % m == 0

            prev_val = None
            for i in range(n):
                if not used[i] and res_list[i] != prev_val:
                    used[i] = True
                    if backtrack(idx + 1, current_sum + (idx + 1) * res_list[i]):
                        return True
                    used[i] = False
                    prev_val = res_list[i]
            return False

        return backtrack(0, 0)

    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue
        if not get_all_possible_sums(residues, m):
            return False, residues
    return True, None

